#ifndef CONFIG_SYSTEM_H
#define CONFIG_SYSTEM_H

#include <string>
#include <string_view>
#include <memory>
#include <unordered_map>
#include <shared_mutex>
#include <functional>
#include <typeinfo>
#include <list>
#include <vector>
#include <set>
#include <unordered_set>
#include <map>
#include <sstream>

namespace ConfigSystem {

class VarBase {
public:
    VarBase(const std::string_view name, const std::string_view description) noexcept;
    virtual ~VarBase() noexcept = default;

    std::string_view Name() const noexcept;
    std::string_view Description() const noexcept;

    virtual std::string ToString() const noexcept = 0;
    virtual void FromString(std::string_view str) = 0;

protected:
    std::string name_;
    std::string description_;
};

template <typename T, typename FromStr = VarConverter<std::string, T>, typename ToStr = VarConverter<T, std::string>>
class Var : public VarBase {
public:
    Var(const std::string_view name, const T& default_val, const std::string_view description = "") noexcept;

private:
    // Deleted copy constructor and assignment operator
    Var(const Var&) = delete;
    Var& operator=(const Var&) = delete;

    // Deleted move constructor and assignment operator
    Var(Var&&) = delete;
    Var& operator=(Var&&) = delete;

public:
    std::string ToString() const noexcept override;
    void FromString(const std::string_view str) override;

    T GetValue() const noexcept;
    void SetValue(const T& val) noexcept;

    std::string_view TypeName() const noexcept;

    void RemoveListener(const std::uint64_t key) noexcept;
    std::uint64_t AddListener(OnChange listener) noexcept;
    void ClearListeners() noexcept;

private:
    T val_;
    std::shared_mutex mtx_;
    std::unordered_map<std::uint64_t, OnChange> listeners_;
};

using OnChange = std::function<void(const VarBase&)>;

class Config {
public:
    Config(const std::string_view name) noexcept;

private:
    // Deleted copy constructor and assignment operator
    Config(const Config&) = delete;
    Config& operator=(const Config&) = delete;

    // Deleted move constructor and assignment operator
    Config(Config&&) = delete;
    Config& operator=(Config&&) = delete;

public:
    std::string_view Name() const noexcept;

    template <typename T>
    typename Var<T>::Ptr Lookup(const std::string_view name, const T& default_val, const std::string_view description = "");

    template <typename T>
    typename Var<T>::Ptr Lookup(const std::string_view name) const;

    VarBase::Ptr LookupBase(std::string_view name) const noexcept;

    void LoadYaml(const YAML::Node& root);

    void Visit(std::function<void(VarBase::Ptr)> visitor) const noexcept;

    static Config::Ptr RootConfig() noexcept;

private:
    std::string name_;
    std::shared_mutex mtx_;
    std::unordered_map<std::string, VarBase::Ptr> vars_;
};

template <typename From, typename To>
class VarConverter {
public:
    To operator()(const From& val) const noexcept;
};

// Specializations for VarConverter

template <typename T>
VarConverter<T, std::string> constexpr to_string_converter{};

VarConverter<std::string, std::string> constexpr identity_string_converter{};

template <typename To>
VarConverter<std::string, To> constexpr string_to_type_converter{};

VarConverter<std::string, std::list<int>> constexpr string_to_list_converter{};
}
#endif // CONFIG_SYSTEM_H

#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <sstream>

#include "config_system.h"

namespace ConfigSystem {

template <typename From, typename To>
To VarConverter<From, To>::operator()(const From& val) const noexcept {
    std::stringstream ss;
    ss << val;
    To result;
    ss >> result;
    return result;
}

template <typename T>
VarConverter<T, std::string> constexpr to_string_converter{};

VarConverter<std::string, std::string> constexpr identity_string_converter{};

template <typename To>
VarConverter<std::string, To> constexpr string_to_type_converter{};

VarConverter<std::string, std::list<int>> constexpr string_to_list_converter{};
}
